SELECT id, customer_id, device, country, LAST_VALUE(country, TRUE) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country, ROW_NUMBER() OVER (PARTITION BY YEAR(started_at) ORDER BY started_at ASC, id ASC) AS event_seq, FIRST_VALUE(country) IGNORE NULLS OVER w_hist AS first_known_country, LAST_VALUE(country) IGNORE NULLS OVER (ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country_2 FROM sessions WHERE country IN ('TH', 'DE') WINDOW w_hist AS (PARTITION BY customer_id ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
